package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
@WebServlet("/updateProblem") public class UpdateProblemServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||!"admin".equals(h.getAttribute("role"))){s.sendRedirect("login.html");return;}try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("UPDATE problems SET status=?,admin_remark=? WHERE id=?")){q.setString(1,r.getParameter("status"));q.setString(2,r.getParameter("remark"));q.setInt(3,Integer.parseInt(r.getParameter("id")));q.executeUpdate();s.sendRedirect("admin-dashboard.jsp?success=updated");}catch(Exception e){e.printStackTrace();s.sendRedirect("admin-dashboard.jsp?error=database");}}}
